import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} linear factors are multiplied to form P(x) = product over i = 1 to {alpha} of (1 + (-1)^(i + {delta}) * ({p} * i + {q}) * x). Let C_{gamma} be the coefficient of x^{gamma} in P(x). Find the absolute value |C_{gamma}|.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Try multiple times to ensure a non-trivial, sufficiently hard instance.
for _ in range(100):
    alpha = rng.randint(12, 24)
    gamma = rng.choice([3, 4])
    delta = rng.randint(0, 1)
    p = rng.randint(1, 5)
    q = rng.randint(0, 8)
    # Build t_i = (-1)^(i+delta) * (p*i + q)
    t = []
    for i in range(1, alpha + 1):
        s = 1 if ((i + delta) % 2 == 0) else -1
        t.append(s * (p * i + q))
    # Ensure alternating signs actually occur
    if not (min(t) < 0 and max(t) > 0):
        continue
    # Compute the coefficient of x^gamma via DP on elementary symmetric sums
    g = gamma
    e = [0] * (g + 1)
    e[0] = 1
    for val in t:
        for k in range(g, 0, -1):
            e[k] += val * e[k - 1]
    coeff = e[g]
    ans = abs(coeff)
    # Filter out trivial instances
    if coeff == 0 or ans <= 100:
        continue
    return {'alpha': alpha, 'gamma': g, 'delta': delta, 'p': p, 'q': q}
# Fallback in case randomness fails; chosen to be non-trivial in practice
return {'alpha': 18, 'gamma': 3, 'delta': 1, 'p': 2, 'q': 3}

    def verifier(assign):
# Verify structure and compute the correct answer.
try:
    alpha = int(assign['alpha'])
    gamma = int(assign['gamma'])
    delta = int(assign['delta'])
    p = int(assign['p'])
    q = int(assign['q'])
except Exception:
    # Missing or malformed parameters
    return (False, None)
# Domain checks to ensure non-trivial difficulty
if not (12 <= alpha <= 100):
    # Too small or too large alpha
    return (False, None)
if gamma not in (3, 4):
    # We only allow 3 or 4 to ensure advanced symmetric sum computation
    return (False, None)
if not (gamma <= alpha):
    return (False, None)
if delta not in (0, 1):
    return (False, None)
if not (1 <= p <= 10):
    return (False, None)
if not (0 <= q <= 50):
    return (False, None)
# Build the sequence t_i = (-1)^(i+delta) * (p*i + q)
t = []
for i in range(1, alpha + 1):
    s = 1 if ((i + delta) % 2 == 0) else -1
    t.append(s * (p * i + q))
# Ensure both positive and negative entries exist to avoid triviality
if not (min(t) < 0 and max(t) > 0):
    # No true alternation in sign magnitudes
    return (False, None)
# Compute coefficient of x^gamma via DP (elementary symmetric sums)
e = [0] * (gamma + 1)
e[0] = 1
for val in t:
    for k in range(gamma, 0, -1):
        e[k] += val * e[k - 1]
coeff = e[gamma]
ans = abs(coeff)
# Enforce non-trivial magnitude to avoid easy guessing
if ans <= 100:
    return (False, None)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

